"""Tests for tasks_api.models — Tag, Task, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── TaskStatus ──────────────────────────────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_from_string(self):
        assert TaskStatus("pending") is TaskStatus.PENDING
        assert TaskStatus("done") is TaskStatus.DONE

    def test_invalid_value_raises(self):
        with pytest.raises(ValueError):
            TaskStatus("invalid")


# ── TaskPriority ────────────────────────────────────────────────────────

class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2

    def test_high_sorts_before_low(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.LOW)


# ── Tag ─────────────────────────────────────────────────────────────────

class TestTag:
    def test_normalizes_to_lowercase(self):
        assert Tag("Urgent").name == "urgent"

    def test_strips_whitespace(self):
        assert Tag("  bug  ").name == "bug"

    def test_allows_hyphens_and_underscores(self):
        assert Tag("high-priority").name == "high-priority"
        assert Tag("work_item").name == "work_item"

    def test_allows_alphanumeric(self):
        assert Tag("v2").name == "v2"

    def test_empty_name_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_exactly_32_chars_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_character_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("no spaces")

    def test_special_chars_raise(self):
        for ch in ["@", "!", ".", "/", "+", "="]:
            with pytest.raises(ValueError, match="illegal character"):
                Tag(f"bad{ch}tag")

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]


# ── Task ────────────────────────────────────────────────────────────────

class TestTask:
    def test_defaults(self):
        task = Task(id=1, title="Test")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []
        assert isinstance(task.created_at, datetime)

    def test_is_overdue_true(self):
        past = datetime(2026, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Overdue", due_at=past)
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is True

    def test_is_overdue_false_when_no_due_date(self):
        task = Task(id=1, title="No due")
        assert task.is_overdue(datetime.now(timezone.utc)) is False

    def test_is_overdue_false_when_done(self):
        past = datetime(2026, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Done", due_at=past, status=TaskStatus.DONE)
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_is_overdue_false_when_due_in_future(self):
        future = datetime(2027, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Future", due_at=future)
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_task_with_tags(self):
        task = Task(id=1, title="Tagged", tags=[Tag("urgent"), Tag("bug")])
        assert len(task.tags) == 2
        assert task.tags[0].name == "urgent"

